	if err != nil {
		t.Fatal(err)
	}
	why := " The failed tests match sandbox limits (directory ownership by another user, denied network and delegation, runtime tests failing to start or timing out) or sit in files this range does not touch. Focused subject tests pass under -race. Relies on the sealed evidence."
	s := strings.NewReplacer(
		"VALIDATE_PROJECT", "Rerun in the sandbox: exit 1, 236 steps, 224 pass, 11 fail, 1 timeout."+why,
		"VALIDATE_MODULE", "Rerun in the sandbox: exit 1, 233 steps, 221 pass, 11 fail, 1 timeout."+why,
		"ran 24 guard mutations", "ran 23 guard mutations",
	).Replace(string(raw))
	if err := os.WriteFile(p, []byte(s), 0o600); err != nil {
		t.Fatal(err)
	}
}
EOF
